const sourceItems = $('Loop Source File').all();

// Map to individual items
return sourceItems.map(item => {
  return {
    json: {
      id: item.json.id
    }
  };
});

// Get all incoming items from the previous node
const items = $input.all();

// Process each item in the array
return items.map(item => {
  const text = item.json.chatInput || "";

  // Split by spaces to count words
  const wordCount = text.trim().split(/\s+/).filter(word => word.length > 0).length;

  // Validate that the word count falls strictly between 10 and 5000 words
  const isValidPhrase = wordCount >= 10 && wordCount <= 5000;

  return {
    json: {
      ...item.json,
      wordCount: wordCount,
      isValidPhrase: isValidPhrase
    }
  };
});

