BEGIN;

-- 1. Set search buffer slightly higher than your LIMIT for index accuracy
SET LOCAL hnsw.ef_search = 45;

-- 2. Force Postgres to prioritize the HNSW index over full-table scans
SET LOCAL enable_seqscan = off;

-- 3. Execute the temporary matching calculation
DROP TABLE IF EXISTS temp_chunk_matches;

CREATE TABLE temp_chunk_matches AS
SELECT
    temp.id AS query_chunk_id,
    temp.text AS query_content,
    main.id AS matched_chunk_id,
    main.text AS matched_content,
    main.similarity
FROM n8n_temp_vectors temp
CROSS JOIN LATERAL (
    SELECT id, text, (1 - (embedding <=> temp.embedding)) AS similarity
    FROM n8n_vectors
    WHERE (1 - (embedding <=> temp.embedding)) > 0.80
    ORDER BY embedding <=> temp.embedding
    LIMIT 5
) main;

COMMIT;

BEGIN;

DROP TABLE IF EXISTS temp_page_centroids;

CREATE TABLE temp_page_centroids AS
SELECT
    AVG(embedding) AS centroid_embedding
FROM n8n_temp_vectors;

COMMIT;

BEGIN;

SET LOCAL hnsw.ef_search = 45;
SET LOCAL enable_seqscan = off;

DROP TABLE IF EXISTS temp_centroid_matches;

CREATE TABLE temp_centroid_matches AS
SELECT
    c.page_url AS target_page_url,
    (1 - (c.centroid_embedding <=> t.centroid_embedding)) AS macro_similarity_score
FROM temp_page_centroids t
CROSS JOIN LATERAL (
    SELECT
        page_url,
        centroid_embedding
    FROM page_centroids
    ORDER BY centroid_embedding <=> t.centroid_embedding
    LIMIT 10
) c;

COMMIT;
